import{z as i,x as l,o as B,c as F,q as n,j as s,D as e,d as a,s as o,S as t,b as A}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"密码学工程收束","description":"","frontmatter":{"title":"密码学工程收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ce-map.md","filePath":"cs/ce-map.md","lastUpdated":1791413859000}'),C={name:"cs/ce-map.md"};function D(d,E,c,p,h,m){const r=l("Mermaid");return B(),F("div",null,[E[2]||(E[2]=n('<h1 id="密码学工程收束" tabindex="-1">密码学工程收束 <a class="header-anchor" href="#密码学工程收束" aria-label="Permalink to &quot;密码学工程收束&quot;">​</a></h1><div class="epigraph"><p>密码工程这几十年的真实进展，不在发明更多原语，而在把「使用者可能做错的选择」一项一项从接口里拿走。</p><footer>—— 据 Ferguson, Schneier and Kohno, *Cryptography Engineering*；Bernstein 的 Curve25519 与 Ed25519 设计口径 整理</footer></div><p><a href="/cs/ce-postquantum-overview">上一课</a>把迁移账排完：机密性先行、混合过渡、对称合同不动。前八课各自钉了合同，但工程决策到来时不会按课序敲门——你要先答「这一层是谁的合同」，再翻对应课。本课不引入新合同，只把九课收成一张可执行的地图：按层检索的顺序与上线前的查漏清单。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束课的缺口不是知识，而是<strong>检索结构</strong>。整理的轴有三条：合同的层次（选型 → 接口 → 身份 → 组合 → 协议 → 实现 → 原料 → 迁移），每层的死法谱系（同一层内的事故长同一个样），与跨层的通用纪律（域分离、失败不可区分、确定性优先）。三层之中，层次轴决定「去哪查」，死法谱系决定「出了事往哪归类」，通用纪律决定「没有对应课的新场景怎么推理」。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按层回收八课。第一层选型（<a href="/cs/ce-symmetric-modes">对称加密模式的实践</a>）：默认 AEAD，nonce 随模式定策略，遗留 CBC 必配 HMAC。第二层接口（<a href="/cs/ce-aead-deep">AEAD 的深入</a>）：四参合同，误用后果分级，SIV 兜底 nonce 不可控的场合。第三层身份（<a href="/cs/ce-signature-practice">签名方案的实践</a>）：\\(k\\) 确定性，验证器当解析器，签钥与协商钥分离。第四层组合（<a href="/cs/ce-kem-hybrid">KEM 与混合加密</a>）：KEM+DEM 替代「公钥加密消息」，认证另叠签名，混合对冲迁移。第五层协议（<a href="/cs/ce-protocol-pitfalls">协议实现的陷阱</a>）：判定预言四个来源，协商进认证，不自写协议。第六层实现（<a href="/cs/ce-side-channels">侧信道</a>）：常量时间三条禁令加盲化，编译产物上复核。第七层原料（<a href="/cs/ce-randomness">随机数</a>）：熵多源混合，系统 CSPRNG，fork 与快照重播种，nonce 双合同。第八层迁移（<a href="/cs/ce-postquantum-overview">后量子概览</a>）：机密性先行，混合封装，对称侧不动。</p>',7)),(B(),s(t,null,{default:e(()=>[o(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E9%80%89%E5%9E%8B%EF%BC%9AAEAD%20%E9%BB%98%E8%AE%A4%EF%BC%8Cnonce%20%E7%AD%96%E7%95%A5%22%5D%20--%3E%20L2%5B%22%E6%8E%A5%E5%8F%A3%EF%BC%9AAEAD%20%E5%9B%9B%E5%8F%82%E5%90%88%E5%90%8C%EF%BC%8CSIV%20%E5%85%9C%E5%BA%95%22%5D%0A%20%20L2%20--%3E%20L3%5B%22%E8%BA%AB%E4%BB%BD%EF%BC%9A%E7%A1%AE%E5%AE%9A%E6%80%A7%20k%EF%BC%8C%E9%AA%8C%E8%AF%81%E5%99%A8%E5%BD%93%E8%A7%A3%E6%9E%90%E5%99%A8%22%5D%0A%20%20L3%20--%3E%20L4%5B%22%E7%BB%84%E5%90%88%EF%BC%9AKEM%20%2B%20DEM%EF%BC%8C%E8%AE%A4%E8%AF%81%E5%8F%A6%E5%8F%A0%22%5D%0A%20%20L4%20--%3E%20L5%5B%22%E5%8D%8F%E8%AE%AE%EF%BC%9A%E5%85%B3%E9%A2%84%E8%A8%80%E6%9C%BA%EF%BC%8C%E5%8D%8F%E5%95%86%E8%BF%9B%E8%AE%A4%E8%AF%81%22%5D%0A%20%20L5%20--%3E%20L6%5B%22%E5%AE%9E%E7%8E%B0%EF%BC%9A%E5%B8%B8%E9%87%8F%E6%97%B6%E9%97%B4%E4%B8%89%E6%9D%A1%E7%A6%81%E4%BB%A4%22%5D%0A%20%20L6%20--%3E%20L7%5B%22%E5%8E%9F%E6%96%99%EF%BC%9A%E7%86%B5%E4%B8%8E%20DRBG%EF%BC%8Cfork%20%E9%87%8D%E6%92%AD%E7%A7%8D%22%5D%0A%20%20L7%20--%3E%20L8%5B%22%E8%BF%81%E7%A7%BB%EF%BC%9A%E6%B7%B7%E5%90%88%E5%B0%81%E8%A3%85%EF%BC%8C%E5%AF%B9%E7%A7%B0%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20L8%20--%3E%20SHIP%5B%22%E4%B8%8A%E7%BA%BF%E6%B8%85%E5%8D%95%E8%BF%87%E4%B8%80%E9%81%8D%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[A("span",{class:"marginnote"},"「死法谱系」就是把同一层里出过的事故按成因归成的清单——可以类比医生分诊：同样是胸痛，急诊科会先按既往病例里最常见的成因排查心脏，而不是随机乱查。有了谱系，新事故先对号入座，再对症下药。")],-1)),E[5]||(E[5]=A("p",null,[a("跨层看，全部事故共用同一条机制："),A("strong",null,"确定性冒充随机性，或随机性缺乏合同"),a("。\\(k\\) 复用是确定性撞上签名方程；nonce 复用是计数器合同没传到调用方；Debian 的熵是确定性原料被当随机卖；fork 后的重复输出是 DRBG 的合同没覆盖进程生命周期。防御也共用一条机制："),A("strong",null,"把正确做法变成默认路径"),a("。X25519 的钳位、Ed25519 的确定性派生、SIV 的合成 IV、HPKE 的标准化封装、TLS 1.3 删掉 CBC——每一个都是在接口层没收使用者的犯错机会，而不是在文档里请求小心。这条机制也解释了本课程的课序为什么「实践」在前、「陷阱与前沿」在后：先立正合同，再审合同会被怎么打穿；两层都过一遍，剩下的才是参数与性能的自由度。")],-1)),(B(),s(t,null,{default:e(()=>[o(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20INC%5B%22%E5%89%8D%E7%BA%BF%E4%BA%8B%E6%95%85%E8%BF%9B%E6%9D%A5%22%5D%20--%3E%20Q1%7B%22%E7%BC%BA%E7%9A%84%E6%98%AF%E9%9A%8F%E6%9C%BA%E6%80%A7%E5%90%88%E5%90%8C%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20F1%5B%22%E5%BD%92%E5%8E%9F%E6%96%99%E6%88%96%E8%BA%AB%E4%BB%BD%E5%B1%82%EF%BC%9A%E6%9F%A5%E7%86%B5%E6%BA%90%E3%80%81DRBG%E3%80%81%E7%A1%AE%E5%AE%9A%E6%80%A7%20k%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20Q2%7B%22%E6%8E%A5%E5%8F%A3%E6%94%BE%E8%A1%8C%E4%BA%86%E5%8D%B1%E9%99%A9%E9%80%89%E9%A1%B9%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20F2%5B%22%E5%BD%92%E9%80%89%E5%9E%8B%E6%88%96%E6%8E%A5%E5%8F%A3%E5%B1%82%EF%BC%9A%E6%8D%A2%20AEAD%20%E6%88%96%20SIV%20%E9%BB%98%E8%AE%A4%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20Q3%7B%22%E4%BA%A4%E4%BA%92%E8%BF%87%E7%A8%8B%E8%A2%AB%E6%89%93%E7%A9%BF%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q3%20--%3E%7C%22%E6%98%AF%22%7C%20F3%5B%22%E5%BD%92%E5%8D%8F%E8%AE%AE%E5%B1%82%EF%BC%9A%E5%8D%8F%E5%95%86%E8%BF%9B%E8%AE%A4%E8%AF%81%EF%BC%8C%E5%85%B3%E5%88%A4%E5%AE%9A%E9%A2%84%E8%A8%80%22%5D%0A%20%20Q3%20--%3E%7C%22%E5%90%A6%22%7C%20F4%5B%22%E5%BD%92%E5%AE%9E%E7%8E%B0%E5%B1%82%EF%BC%9A%E5%B8%B8%E9%87%8F%E6%97%B6%E9%97%B4%E4%B8%8E%E7%9B%B2%E5%8C%96%E5%A4%8D%E6%A0%B8%22%5D%0A%20%20F1%20--%3E%20FIX%5B%22%E5%9B%9E%E5%AF%B9%E5%BA%94%E8%AF%BE%E8%A1%A5%E8%B4%A6%E5%90%8E%E5%A4%8D%E6%A3%80%E6%B8%85%E5%8D%95%22%5D%0A%20%20F2%20--%3E%20FIX%0A%20%20F3%20--%3E%20FIX%0A%20%20F4%20--%3E%20FIX%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p><span class="marginnote">为什么「确定性冒充随机性」值得单独记住：签名时把随机数 \\(k\\) 换成确定值会泄露私钥，但 Ed25519 偏偏用确定性派生的 \\(k\\) 却更安全——区别在于前者是攻击者可预测的确定（比如取消息哈希），后者是只有私钥能算出的确定。可见「确定」本身不是罪，缺合同的确定才是。</span></p><p><span class="marginnote">上线前的最小清单：AEAD 且 nonce 有合同；签名确定性且验证器逐项检查；KEM+DEM 而非自造公钥加密；错误与失败不可区分且常量时间；系统 CSPRNG 且 fork 重播种；协商进认证；密钥有域分离与轮换。七项各对应一课，缺一项就回那一课补账。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程有意留下的界外账：公钥绑名字的 PKI 与证书生态（<a href="/cs/tls-handshake">TLS 握手</a>的入口课已给外观）；对加密数据直接计算的 MPC 与 PIR 路线（见 <a href="/cs/pir">PIR</a>）；格密码与量子算法的数学；硬件安全的功耗层。这四块各自是别的课程的缺口，本课程不再追。<span class="marginnote">常见误区是把「界外」理解成「不重要」：这四块只是不属于本课程的范围，不等于上线产品可以不管。比如你的服务要用证书，PKI 的账照样要算——只是要翻到讲 PKI 的那一课去算，而不是在这张地图里硬找。</span>收束的口径：选型、接口、身份、组合、协议、实现、原料、迁移，八层合同到此全部钉完，前线事故回到对应层诊断即可。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>八层地图：选型、接口、身份、组合、协议、实现、原料、迁移；决策先归层再查课。</li><li>全部事故同机制：确定性冒充随机性，或随机性缺乏合同。</li><li>全部防御同机制：把正确做法变成默认路径，在接口层没收犯错机会。</li><li>界外四块：PKI、MPC/PIR、格数学、硬件功耗层，各是别的课程的缺口。</li><li>出处：Ferguson, Schneier and Kohno, <em>Cryptography Engineering</em>；Bernstein（Curve25519）与 RFC 7748/8032；NIST SP 800-38D 与 FIPS 203/204/205。</li></ul>',6))])}const P=i(C,[["render",D]]);export{u as __pageData,P as default};
